    if not cwd or cwd[0] != '/':
        return None

    # Normalize cwd to remove trailing slash
    if cwd != '/' and cwd.endswith('/'):
        cwd = cwd.rstrip('/')

    # Start with cwd if path is relative
    if not path or path[0] != '/':
        current = cwd
