        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            # Get the symlink target
            target = links[current]

            # Resolve the target relative to the directory containing the link
            if target[0] == '/':
                # Absolute target
                current = ''
                target_components = target.split('/')
            else:
                # Relative target - relative to the directory containing the link
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]
                target_components = target.split('/')

            # Insert remaining components from original path
            target_components.extend(components[i:])
            components = target_components
            i = 0

    # Handle final result
    if current == '':
        current = '/'

    # Remove trailing slash unless it's the root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

